INSERT INTO public."GalleryAlbum" (id, title, slug, "shortDescription", "fullDescription", category, "eventDate", venue, "organizedBy", "coverImage", "isFeatured", "isPublished", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkpl003cona034bzid2p', 'Singa Pen Entrepreneurship Bazaar & Food Stall', 'singa-pen-entrepreneurship-bazaar-food-stall', 'An on-campus exhibition showcasing handmade items, bakery confectioneries, custom tailoring, and organic cosmetics made by student micro-ventures.', 'This event provides a safe ecosystem for student-led businesses to run active commerce stalls, receive feedback from faculty, and gain exposure to retail and pricing models.', 'SINGA_PEN_ACTIVITY', '2026-01-22 00:00:00', 'College Quadrangle Lawn', 'Singa Pen Club Entrepreneurship Wing', '/uploads/demo_album3_cover.png', true, true, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:22.039', '2026-07-22 06:08:22.039');
INSERT INTO public."GalleryAlbum" (id, title, slug, "shortDescription", "fullDescription", category, "eventDate", venue, "organizedBy", "coverImage", "isFeatured", "isPublished", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkjq002wona0260xv4ft', 'Pudhumai Penn Induction & Celebration 2025', 'pudhumai-penn-induction-celebration-2025', 'Celebrating the induction of new scholarship recipients under the Pudhumai Penn program, empowering them with academic stipends.', 'The Pudhumai Penn induction event by the Govt of Tamil Nadu aims to encourage girls to pursue college degrees. It credits Rs 1,000 monthly directly into the bank accounts of girls who studied from class 6th to 12th in government schools.', 'CELEBRATION', '2025-10-15 00:00:00', 'Main College Auditorium', 'Women''s Empowerment Cell Coordinator & Singa Pen Student Board', '/uploads/demo_album1_cover.png', true, true, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.828', '2026-08-16 01:30:50.087');
INSERT INTO public."GalleryAlbum" (id, title, slug, "shortDescription", "fullDescription", category, "eventDate", venue, "organizedBy", "coverImage", "isFeatured", "isPublished", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolknl0034ona06gm48ofo', 'Naan Mudhalvan Advanced Python & AI Bootcamp', 'naan-mudhalvan-advanced-python-ai-bootcamp', 'Hands-on coding bootcamp covering data processing, web scraping, and machine learning models for college girl developers.', 'Naan Mudhalvan is a state-wide skill program initiated by the Hon’ble Chief Minister of Tamil Nadu. It provides industry-grade certifications in frontend programming, IoT, logistics, and data sciences to equip young college women for corporate recruitments.', 'WORKSHOP', '2025-11-20 00:00:00', 'Central Computer Science Lab', 'Tamil Nadu Skill Development Corporation in association with Women''s Empowerment Cell', '/uploads/demo_album2_cover.png', true, true, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.968', '2026-08-16 01:30:50.104');
