INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkae002cona0dqwmrr0u', 'Moovalur Ramamirtham Ammaiyar Pudhumai Penn Scheme', 'moovalur-ramamirtham-ammaiyar-pudhumai-penn-scheme', 'Provides monthly financial assistance of Rs 1,000 for government school girl students pursuing higher education.', 'The Pudhumai Penn scheme by the Govt of Tamil Nadu aims to encourage girls to pursue college degrees. It credits Rs 1,000 monthly directly into the bank accounts of girls who studied from class 6th to 12th in government schools.', 'Social Welfare and Women Empowerment Department, Tamil Nadu', 'Scholarship', 'Must be a girl student. Must have studied in Government Schools of Tamil Nadu from 6th to 12th standard. Pursuing undergraduate degree or diploma.', 'Rs 1,000 per month paid directly until course completion.', '["Government School Transfer Certificate","Aadhaar Card","College Admission Receipt","Bank Passbook Front Page"]', 'Apply online through the Penkalvi web portal or coordinate with the Women''s Empowerment Cell administrative desk.', 'https://penkalvi.tn.gov.in', '2026-06-01 00:00:00', '2027-05-31 00:00:00', 'Toll-free student helpline: 14417, or contact Prof. Meera Nair (Women''s Empowerment Cell Coordinator).', 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.495', '2026-08-16 01:30:50.142');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkcl002eona0zs1pg97m', 'Tamil Nadu Naan Mudhalvan Skill Development Scheme', 'tamil-nadu-naan-mudhalvan-skill-development-scheme', 'Free high-tech skill training and certification courses in AI, coding, and design to increase college girls employability.', 'Naan Mudhalvan is a state-wide skill program initiated by the Hon’ble Chief Minister of Tamil Nadu. It provides industry-grade certifications in frontend programming, IoT, logistics, and data sciences to equip young college women for corporate recruitments.', 'Tamil Nadu Skill Development Corporation (TNSDC)', 'Skill Development', 'Currently enrolled undergraduate or postgraduate college students in registered Tamil Nadu universities.', 'Free access to industry-curated coding platforms, Microsoft certifications, and direct placement drives.', '["College Identity Card","Aadhaar Card","Mark Sheets (Class 10th & 12th)"]', 'Register on the Naan Mudhalvan portal using college credentials and choose your desired tech track.', 'https://www.naanmudhalvan.tn.gov.in', '2026-07-01 00:00:00', '2027-03-31 00:00:00', 'Naan Mudhalvan helpline: 044-22500100', 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.573', '2026-08-09 12:56:24.826');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkdl002iona04g459br0', 'Pragati Scholarship Scheme for Girl Students', 'pragati-scholarship-scheme-for-girl-students', 'Provides Rs 50,000 per annum to girls pursuing professional degree and diploma education.', 'Pragati is a scheme implemented by AICTE to provide financial support to girl students for technical and professional education. It aims to empower girls and promote technical education among them.', 'All India Council for Technical Education (AICTE)', 'Education', 'Maximum two girl children per family. Family income must be less than Rs 8 Lakh per annum. Admitted to 1st year degree/diploma program of AICTE approved colleges.', 'Rs 50,000 per annum towards college tuition, computer, and book purchases.', '["Annual Family Income Certificate","College Fee Receipt","AICTE Admission Letter","Aadhaar Card"]', 'Apply online through the National Scholarship Portal (NSP) and submit verifying files to the college administration.', 'https://scholarships.gov.in', '2026-09-01 00:00:00', '2026-12-31 00:00:00', 'AICTE student support help desk: pragati@aicte-india.org', 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.609', '2026-08-09 12:56:24.826');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolke6002kona08ew2alha', 'Prime Minister Employment Generation Programme (PMEGP) for Women', 'prime-minister-employment-generation-programme-pmegp-for-women', 'Credit-linked subsidy program providing up to 35% margin money for launching manufacturing or service startups.', 'A major central credit scheme aimed at creating micro-enterprises. Under PMEGP, women entrepreneurs in rural and urban areas receive highly subsidized loans with government margins to launch small production mills or tailoring units.', 'Ministry of Micro, Small and Medium Enterprises (MSME)', 'Startup Support', 'Any individual female above 18 years of age. Minimum standard 8th pass for manufacturing projects costing above Rs 10 Lakhs.', 'Up to 35% subsidy on project costs. Loan up to Rs 50 Lakhs for manufacturing, and Rs 20 Lakhs for service business.', '["Detailed Project Report (DPR)","Aadhaar Card","Educational Certificate","Community Certificate"]', 'Apply online via the KVIC PMEGP portal, listing our college incubation desk as reference center.', 'https://www.kviconline.gov.in/pmegpeportal', '2026-04-01 00:00:00', '2027-03-31 00:00:00', NULL, 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.63', '2026-08-09 12:56:24.826');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkfk002mona07mr8zqvg', 'Tamil Nadu Rural Women Entrepreneurship Development Scheme', 'tamil-nadu-rural-women-entrepreneurship-development-scheme', 'Micro-grants and marketing training camps to help college girls launch rural cottage businesses.', 'This state initiative focuses on training college girls from rural regions in handmade wellness goods, tailoring, organic beauty lotions, and agro-foods, coupled with setting up college campus sales booths.', 'Social Welfare Board of Tamil Nadu', 'Rural Women', 'College girls hailing from semi-urban or village panchayats in Tamil Nadu.', 'Free 2-week entrepreneurship workshop on campus, Rs 15,000 initial micro-grant for buying production raw materials.', '["Village Residence Certificate","College Bonafide","Community Certificate"]', 'Register on campus with the Singa Pen Club Student Board during the startup week.', 'https://www.tn.gov.in/dept/socialwelfare', '2026-10-01 00:00:00', '2027-02-28 00:00:00', NULL, 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.68', '2026-08-09 12:56:24.826');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkcy002gona0mlv0nlgb', 'Mahila Co-operative Startup Funding Initiative', 'mahila-co-operative-startup-funding-initiative', 'Collateral-free low interest commercial micro-loans of up to Rs 5 Lakhs for women student entrepreneurs.', 'A custom national funding program designed specifically to convert young women student projects into real micro-ventures. This provides small business loans with zero collateral requirement and highly subsidized interest rates.', 'National Cooperative Development Corporation', 'Entrepreneurship', 'Women college students or recent alumni (within 3 years of passing) aged 18 to 28. Business plan must be verified by college incubation desk.', 'Low interest rate (4% per annum). Collateral-free loan up to Rs 5,000,000. 12 months repayment holiday.', '["Business Pitch Deck","College Bonafide Certificate","Project Report Co-Signed by Faculty","PAN Card & Aadhaar"]', 'Submit your formal business idea and proposal via the Women''s Empowerment Cell and incubation desk to be forwarded to partner banks.', 'https://www.ncdc.in', '2026-04-01 00:00:00', '2027-03-31 00:00:00', 'Startup empowerment wing: startup-women@ncdc.in', 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.587', '2026-08-16 01:30:50.13');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmslso8cj0001onbks8dcqjlu', 'Moovalur Ramamirtham Ammaiyar Higher Education Assurance Scheme - Pudhumai Penn', 'pudhumai-penn-higher-education-assurance', 'Monthly assistance of Rs.1,000 for eligible girl students from Tamil Nadu government schools pursuing higher education.', 'Verified on 2026-08-09 from the official Tamil Nadu Social Welfare & Women Empowerment Department portal. The scheme supports eligible girl students who studied from Classes 6 to 12 in government schools and continue into recognized higher education courses.', 'Tamil Nadu Social Welfare & Women Empowerment Department', 'Education', 'Girl students who studied Classes 6 to 12 in Tamil Nadu government schools and are enrolled in recognized undergraduate, diploma, ITI, or eligible higher education courses.', 'Rs.1,000 per month through direct benefit transfer until uninterrupted completion of the eligible first higher education course.', '["Student identity proof","Government school study proof","College bonafide certificate","Bank account details"]', 'Apply through the official Pudhumai Penn / Penkalvi process with college coordination where required.', 'https://www.tnsocialwelfare.tn.gov.in/en/specilisationswoman-welfare/pudhumai-penn', '2026-08-09 00:00:00', NULL, 'Source: Official Tamil Nadu Social Welfare & Women Empowerment Department. Verified on 2026-08-09.', 'ACTIVE', true, 'cmrvoli0a0000ona00wfohrl6', '2026-08-09 12:44:25.024', '2026-08-09 12:56:24.897');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmslso8d90003onbkvbua75f7', 'Tamil Nadu Women Entrepreneurs Empowerment Scheme (TWEES)', 'tamil-nadu-women-entrepreneurs-empowerment-scheme-twees', 'Tamil Nadu MSME scheme supporting women entrepreneurs with enterprise assistance through the official TWEES portal.', 'Verified on 2026-08-09 from the official Tamil Nadu MSME TWEES portal, which shows FY 2026-2027 scheme dashboard and online application modules.', 'Tamil Nadu Micro, Small and Medium Enterprises Department', 'Entrepreneurship', 'Women entrepreneurs meeting the eligibility conditions published by the Tamil Nadu MSME TWEES portal.', 'Enterprise-support assistance as per the current TWEES guidelines, eligibility checks, and application process published by Tamil Nadu MSME.', '["Identity proof","Enterprise details","Project or business documents","Documents listed by the official TWEES portal"]', 'Use the official TWEES portal eligibility, guidelines, and online application flow.', 'https://www.msmeonline.tn.gov.in/twees/index.php', '2026-08-09 00:00:00', NULL, 'Source: Official Tamil Nadu MSME TWEES portal. Verified on 2026-08-09.', 'ACTIVE', true, 'cmrvoli0a0000ona00wfohrl6', '2026-08-09 12:44:25.053', '2026-08-09 12:56:24.956');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmslso8dn0005onbklkzi6a45', 'Stand-Up India', 'stand-up-india-women-entrepreneurs', 'Bank loan facilitation for women entrepreneurs setting up greenfield enterprises.', 'Verified on 2026-08-09 from Government of India myScheme. The scheme facilitates bank loans for SC/ST and women entrepreneurs for greenfield enterprise setup.', 'Government of India - Ministry of Finance / myScheme', 'Startup Support', 'Women entrepreneurs aged 18 or above setting up eligible greenfield enterprises, subject to bank and official scheme conditions.', 'Bank loan facilitation for eligible enterprise setup as described on the official myScheme / Stand-Up India listing.', '["Identity proof","Business plan","Enterprise and bank documents","Documents required by the lending bank"]', 'Review eligibility through myScheme and apply via the official Stand-Up India / bank-linked process.', 'https://www.myscheme.gov.in/schemes/sui', '2026-08-09 00:00:00', NULL, 'Source: Government of India myScheme. Verified on 2026-08-09.', 'ACTIVE', true, 'cmrvoli0a0000ona00wfohrl6', '2026-08-09 12:44:25.067', '2026-08-09 12:56:24.974');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmslso8e60007onbk3iqe6x7t', 'New Swarnima Scheme for Women', 'new-swarnima-scheme-for-women', 'Loan support for women entrepreneurs from backward classes through the official government scheme listing.', 'Verified on 2026-08-09 from Government of India myScheme. The listing describes financial support for women entrepreneurs from backward classes.', 'Government of India - myScheme', 'Financial Assistance', 'Women from backward classes meeting the income, age, and lending conditions specified on the official scheme page.', 'Loan support up to the officially specified limit and interest terms published on myScheme.', '["Identity proof","Category or eligibility proof","Income proof","Business purpose documents"]', 'Follow the application instructions and channel specified on the official myScheme page.', 'https://www.myscheme.gov.in/schemes/nssw', '2026-08-09 00:00:00', NULL, 'Source: Government of India myScheme. Verified on 2026-08-09.', 'ACTIVE', false, 'cmrvoli0a0000ona00wfohrl6', '2026-08-09 12:44:25.085', '2026-08-09 12:56:24.993');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmslso8f00009onbkwj1z42o3', 'Mahila Samriddhi Yojana', 'mahila-samriddhi-yojana-women-entrepreneurs', 'Financial support scheme for women entrepreneurs from backward or poor backgrounds.', 'Verified on 2026-08-09 from Government of India myScheme. The listing describes support for women entrepreneurs from backward or poor backgrounds.', 'Government of India - myScheme', 'Entrepreneurship', 'Women entrepreneurs meeting the social, economic, and scheme-specific criteria listed on the official government page.', 'Financial support for eligible women entrepreneurs as provided through the official scheme framework.', '["Identity proof","Eligibility proof","Income proof","Business or self-employment documents"]', 'Use the official myScheme guidance and linked implementation channel.', 'https://www.myscheme.gov.in/schemes/cbssc-msy', '2026-08-09 00:00:00', NULL, 'Source: Government of India myScheme. Verified on 2026-08-09.', 'ACTIVE', false, 'cmrvoli0a0000ona00wfohrl6', '2026-08-09 12:44:25.116', '2026-08-09 12:56:25.013');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkg2002oona0klkn4pps', 'AICTE Saksham Scholarship for Specially Abled Girls', 'aicte-saksham-scholarship-for-specially-abled-girls', 'Provides Rs 50,000 per annum to physically challenged girl students pursuing professional degrees.', 'A specialized AICTE scheme designed to support specially-abled girls in acquiring technical skills. It reduces financial pressure on families and ensures equal access to professional growth.', 'AICTE, Government of India', 'Education', 'Girl student with disability level greater than 40%. Family income below Rs 8 Lakh per year. Currently studying in AICTE degree/diploma.', 'Rs 50,000 per annum credited as direct benefit transfer.', '["Disability Certificate","Income Certificate","College Enrolment Receipt","Bank Passbook"]', 'Register and submit on the National Scholarship Portal under the AICTE Saksham section.', 'https://scholarships.gov.in', '2026-08-15 00:00:00', '2027-01-15 00:00:00', NULL, 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.699', '2026-08-09 12:56:24.826');
INSERT INTO public."GovernmentScheme" (id, title, slug, "shortDescription", "fullDescription", provider, category, eligibility, benefits, "requiredDocuments", "applicationProcess", "officialUrl", "startDate", "endDate", "contactInformation", status, "isFeatured", "createdById", "createdAt", "updatedAt") VALUES ('cmrvolkgn002qona0t62phcy3', 'Aditya Birla Scholarship for Academic Excellence', 'aditya-birla-scholarship-for-academic-excellence', 'Private merit scholarship covering full tuition fees for outstanding girl students in management and tech.', 'The Aditya Birla Group Scholarship program fosters future leadership. It rewards top academic achievers across premier universities, completely sponsoring their tuition, exam, and hostel fees.', 'Aditya Birla Group Foundation', 'Other', 'Girl student in top 15% of university rankings in first semester of tech or management course.', '100% tuition and hostel fee reimbursement. Annual mentorship workshops under corporate heads.', '["First Semester College CGPA Sheet","HSC Mark Sheet","Family Income Tax Returns"]', 'Eligible girls are nominated directly by the college dean to the Aditya Birla Board.', 'https://www.adityabirlascholars.net', '2026-09-01 00:00:00', '2026-10-31 00:00:00', NULL, 'EXPIRED', false, 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.72', '2026-08-09 12:56:24.826');
