INSERT INTO public."SiteContent" (id, "sectionKey", title, content, metadata, "updatedById", "createdAt", "updatedAt") VALUES ('cmrvolkha002sona0gdxjmxkm', 'home', 'Welcome to Singa Pen Portal', 'Empowering young college women through core leadership, modern tech skill development, financial scheme awareness, and entrepreneurial incubation.', '{"heroTitle": "Rise, Lead, and Inspire", "contactEmail": "womenscell@college.edu", "contactPhone": "044-22334455", "heroSubtitle": "Welcome to the Women''s Empowerment Cell of Sankara College of Science and Commerce and Singa Pen Club Portal. A dedicated platform bridging leadership, skill search, and government support for every student.", "empowermentQuote": "“Every girl is a born lioness (Singa Pen). All she needs is a supportive ecosystem, real-world skills, and the confidence to conquer her dreams.”"}', 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.742', '2026-08-16 01:29:39.029');
INSERT INTO public."SiteContent" (id, "sectionKey", title, content, metadata, "updatedById", "createdAt", "updatedAt") VALUES ('cmrvolkid002uona0o1n2hikf', 'about', 'Women''s Empowerment Cell & Singa Pen Club', 'The Women''s Empowerment Cell of Sankara College of Science and Commerce has been a pillar of safety, empowerment, and leadership since its inception. In 2024, the "Singa Pen" (Lioness) club was established to serve as the student-led action wing of the cell.', '{"vision": "To build a secure, progressive, and equitable campus ecosystem where young women emerge as self-reliant leaders, tech innovators, and successful entrepreneurs.", "mission": "To organize high-impact training workshops, raise direct awareness about government scholarships/subsidies, mentor micro-business plans, and display student talent to the academic community.", "objectives": ["Organize hands-on skill workshops (coding, tailoring, arts, wellness).", "Directly facilitate student applications for state and central women schemes.", "Act as an incubator for female-led business proposals on campus.", "Maintain a searchable skills database for college collaborations."]}', 'cmrvoli0a0000ona00wfohrl6', '2026-07-22 06:08:21.781', '2026-08-16 01:29:38.848');
